{"status": 0, "output": "def order_changes(directory, classes, accounts_by_code, files, declared=None, days=()):
    """Optional orders/*.json: temporary absolute clocks, and their withdrawals.

    An *activation* row names a class, a 原定日, the accounts it applies to and the
    UTC clock that day is to be held at instead.  It is an instruction about a
    *scheduled* day, so an unknown day is refused rather than invented, and only
    the named accounts change: the other accounts, the other days and the other
    classes keep their annex / venue clock.

    A *withdrawal* row names no clock but a `target`: for the listed accounts on
    that day the named activation is taken back, so those invitations fall back
    to the contract clock that was never withdrawn.  Accounts the committee did
    not name keep the temporary clock.

    Rows are applied in (version, file name) order, so the newest issuance wins
    and a replayed arrival reaches the same state.  A document may carry
    `status`; if it does, it must be signed.

    -> (changes, withdrawn): changes maps (account, code, day) to (time, order id),
    withdrawn maps (account, code, day) to the order id that was taken back.
    """
    folder = os.path.join(directory, "orders")
    if not os.path.isdir(folder):
        return {}, {}
    wanted = {day for day in days}
    by_code = {code: [entry["account"] for entry in entries]
               for code, entries in accounts_by_code.items()}
    changes, withdrawn = {}, {}
    for name in sorted(os.listdir(folder)):
        if not name.endswith(".json"):
            continue
        rel = f"orders/{name}"
        files.append(rel)
        document = load_json(os.path.join(folder, name))
        issued = document.get("version")
        if issued is not None:
            if not isinstance(issued, int) or isinstance(issued, bool) or issued < 1:
                raise ValueError(f"{rel} names no logical version: {issued!r}")
            if declared is not None and issued > declared:
                raise ValueError(f"{rel} is issued for logical version {issued}, but this arrival"
                                 f" declares {declared}")
        status = document.get("status")
        if status is not None:
            signed(document, rel)
        rows = document.get("rows")
        if not isinstance(rows, list) or not rows:
            raise ValueError(f"{rel} names no rows")
        for row in rows:
            code = row.get("code")
            target = row.get("target")
            if code is not None and code not in classes and not target:
                raise ValueError(f"{rel} names class {code!r}, which the schedule does not have")
            written = row.get("days") or ([row["day"]] if row.get("day") else [])
            if not written:
                raise ValueError(f"{rel} names no day")
            accounts = row.get("accounts")
            if accounts is None:
                if target:
                    raise ValueError(f"{rel} withdraws {target} without saying whose it is")
                accounts = by_code.get(code, [])
            accounts = [str(account).strip() for account in accounts]
            order_id = str(row.get("id") or name)
            for day_text in written:
                try:
                    day = date.fromisoformat(str(day_text))
                except (TypeError, ValueError):
                    raise ValueError(f"{rel} names a day that is not a date: {day_text!r}")
                if day not in wanted:
                    raise ValueError(f"{rel} names {day}, which the schedule does not have")
                if target:                                  # 撤回
                    taken = [key for key, (_, made_by) in changes.items()
                             if made_by == str(target) and key[2] == day
                             and key[0] in accounts and (code is None or key[1] == code)]
                    if not taken:
                        raise ValueError(f"{rel} withdraws {target} for {accounts} on {day},"
                                         f" but nothing by that name is in force there")
                    for key in taken:
                        del changes[key]
                        withdrawn[key] = str(target)
                    continue
                unknown = [account for account in accounts
                           if account not in by_code.get(code, [])]
                if unknown:
                    raise ValueError(f"{rel} names {unknown}, who have no {code} registration")
                per_account = row.get("utc_by_account") or {}
                written_clock = row.get("utc_clock") or row.get("clock")
                for account in accounts:
                    raw = per_account.get(account, written_clock)
                    if not raw:
                        raise ValueError(f"{rel} gives no clock for {account} / {code} / {day}")
                    changes[(account, code, day)] = (clock_value(raw, f"{rel} / {account}"),
                                                     order_id)
                    withdrawn.pop((account, code, day), None)
    return changes, withdrawn


